def iter_lines(self, chunk_size=ITER_CHUNK_SIZE, decode_unicode=None, delimiter=None):
    """Iterates over the response data, one line at a time.  When
    stream=True is set on the request, this avoids reading the
    content at once into memory for large responses.

    .. note:: This method is not reentrant safe.
    """

    pending = None

    for chunk in self.iter_content(chunk_size=chunk_size, decode_unicode=decode_unicode):

        if pending is not None:
            chunk = pending + chunk

        if delimiter:
            lines = chunk.split(delimiter)
        else:
            lines = chunk.splitlines()

        if lines and lines[-1] and chunk and lines[-1][-1] == chunk[-1]:
            pending = lines.pop()
        else:
            pending = None

        for line in lines:
            yield line

    if pending is not None:
        yield pending

def iter_content(self, chunk_size=1, decode_unicode=False):
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    If decode_unicode is True, content will be decoded using the best
    available encoding based on the response.
    """
    def generate():
        try:
            # Special case for urllib3.
            try:
                for chunk in self.raw.stream(chunk_size, decode_content=True):
                    yield chunk
            except IncompleteRead as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
        except AttributeError:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    # simulate reading small chunks of the content
    reused_chunks = iter_slices(self._content, chunk_size)

    stream_chunks = generate()

    chunks = reused_chunks if self._content_consumed else stream_chunks

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def iter_content(self, chunk_size=1, decode_unicode=False):
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    If decode_unicode is True, content will be decoded using the best
    available encoding based on the response.
    """
    def generate():
        try:
            # Special case for urllib3.
            try:
                for chunk in self.raw.stream(chunk_size, decode_content=True):
                    yield chunk
            except ProtocolError as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
            except ReadTimeoutError as e:
                raise ConnectionError(e)
        except AttributeError:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    if self._content_consumed and isinstance(self._content, bool):
        raise StreamConsumedError()
    # simulate reading small chunks of the content
    reused_chunks = iter_slices(self._content, chunk_size)

    stream_chunks = generate()

    chunks = reused_chunks if self._content_consumed else stream_chunks

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def path_url(self):
    """Build the path URL to use."""

    url = []

    p = urlsplit(self.url)

    path = p.path
    if not path:
        path = '/'

    url.append(path)

    query = p.query
    if query:
        url.append('?')
        url.append(query)

    return ''.join(url)

def collect(self):
    if not getattr(self.obj, "__test__", True):
        return []

    # NB. we avoid random getattrs and peek in the __dict__ instead
    # (XXX originally introduced from a PyPy need, still true?)
    dicts = [getattr(self.obj, "__dict__", {})]
    for basecls in inspect.getmro(self.obj.__class__):
        dicts.append(basecls.__dict__)
    seen = {}
    values = []
    for dic in dicts:
        for name, obj in list(dic.items()):
            if name in seen:
                continue
            seen[name] = True
            res = self._makeitem(name, obj)
            if res is None:
                continue
            if not isinstance(res, list):
                res = [res]
            values.extend(res)
    values.sort(key=lambda item: item.reportinfo()[:2])
    return values

def _getconftest_pathlist(self, name, path):
    try:
        mod, relroots = self.pluginmanager._rget_with_confmod(
            name, path, self.getoption("importmode")
        )
    except KeyError:
        return None
    modpath = py.path.local(mod.__file__).dirpath()
    values = []
    for relroot in relroots:
        if not isinstance(relroot, py.path.local):
            relroot = relroot.replace("/", py.path.local.sep)
            relroot = modpath.join(relroot, abs=True)
        values.append(relroot)
    return values

def __init__(self, rawcode) -> None:
    if not hasattr(rawcode, "co_filename"):
        rawcode = getrawcode(rawcode)
    if not isinstance(rawcode, CodeType):
        raise TypeError("not a code object: {!r}".format(rawcode))
    self.filename = rawcode.co_filename
    self.firstlineno = rawcode.co_firstlineno - 1
    self.name = rawcode.co_name
    self.raw = rawcode

def get_ast(
    self, filepath: str, modname: str, data: Optional[str] = None
) -> nodes.Module:
    """Return an ast(roid) representation of a module or a string.

    :param str filepath: path to checked file.
    :param str modname: The name of the module to be checked.
    :param str data: optional contents of the checked file.
    :returns: the AST
    :rtype: astroid.nodes.Module
    :raises AstroidBuildingError: Whenever we encounter an unexpected exception
    """
    try:
        if data is None:
            return MANAGER.ast_from_file(filepath, modname, source=True)
        return astroid.builder.AstroidBuilder(MANAGER).string_build(
            data, modname, filepath
        )
    except astroid.AstroidSyntaxError as ex:
        # pylint: disable=no-member
        self.add_message(
            "syntax-error",
            line=getattr(ex.error, "lineno", 0),
            col_offset=getattr(ex.error, "offset", None),
            args=str(ex.error),
        )
    except astroid.AstroidBuildingError as ex:
        self.add_message("parse-error", args=ex)
    except Exception as ex:
        traceback.print_exc()
        # We raise BuildingError here as this is essentially an astroid issue
        # Creating an issue template and adding the 'astroid-error' message is handled
        # by caller: _check_files
        raise astroid.AstroidBuildingError(
            "Building error when trying to create ast representation of module '{modname}'",
            modname=modname,
        ) from ex
    return None

def load_command_line_configuration(
    self, args: list[str] | None = None
) -> list[str]:  # pragma: no cover
    """DEPRECATED: Override configuration according to command line parameters.

    return additional arguments
    """
    warnings.warn(
        "load_command_line_configuration has been deprecated. It will be removed in pylint 3.0.",
        DeprecationWarning,
    )
    args = sys.argv[1:] if args is None else list(args)
    (options, args) = self.cmdline_parser.parse_args(args=args)
    for provider in self._nocallback_options:
        config = provider.config
        for attr in config.__dict__.keys():
            value = getattr(options, attr, None)
            if value is None:
                continue
            setattr(config, attr, value)
    return args
